css:
.studiosim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2a1b2e;
    background: linear-gradient(160deg, #faf3f1 0%, #f3e8ef 100%);
    border-radius: 18px;
}

.studiosim-container * {
    box-sizing: border-box;
}

.studiosim-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #3a1230 0%, #6d1f4e 55%, #a8326b 100%);
    color: #fdf2f6;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 12px 32px rgba(58, 18, 48, 0.32);
}

.studiosim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.35rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.studiosim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.3px;
    font-weight: 700;
    color: #f4c977;
    background: rgba(255, 255, 255, 0.12);
    padding: 5px 14px;
    border-radius: 999px;
}

.studiosim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #f6e0ea;
}

.studiosim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #6d1f4e;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.studiosim-period-counter #currentDay,
.studiosim-period-counter #maxPeriods {
    font-weight: 800;
    color: #3a1230;
}

.studiosim-round-name {
    background: #f0d7e5;
    color: #6d1f4e;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.studiosim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a3412;
    background: #fde7d6;
    padding: 4px 12px;
    border-radius: 999px;
}

.studiosim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.studiosim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #ecd8e3;
    box-shadow: 0 4px 14px rgba(58, 18, 48, 0.07);
    border-top: 4px solid #a8326b;
}

.studiosim-card-distinct { border-top-color: #a8326b; }
.studiosim-card-delivery { border-top-color: #2f6f8f; }
.studiosim-card-engage { border-top-color: #1f7a55; }
.studiosim-card-legal { border-top-color: #c98a16; }

.studiosim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8a6a7c;
}

.studiosim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #3a1230;
}

.studiosim-card-distinct .studiosim-value { color: #a8326b; }
.studiosim-card-delivery .studiosim-value { color: #2f6f8f; }
.studiosim-card-engage .studiosim-value { color: #1f7a55; }
.studiosim-card-legal .studiosim-value { color: #1f7a55; }

.studiosim-sublabel {
    font-size: 0.76rem;
    color: #8a6a7c;
    line-height: 1.35;
}

.studiosim-distinct-win .studiosim-value { color: #1f7a55; }
.studiosim-distinct-flat .studiosim-value { color: #c0392b; }

.studiosim-delivery-late .studiosim-value { color: #c0392b; }
.studiosim-delivery-ontime .studiosim-value { color: #1f7a55; }

.studiosim-legal-flag { border-top-color: #c0392b; }
.studiosim-legal-flag .studiosim-value { color: #c0392b; }

.studiosim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #3a1230;
    color: #fbe8f1;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.studiosim-budget-bar.studiosim-over-budget {
    background: #7a1320;
    color: #ffe2e2;
}

.studiosim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
}

.studiosim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #a8326b;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(58, 18, 48, 0.06);
}

.studiosim-briefing-icon {
    font-size: 1.85rem;
    line-height: 1;
}

.studiosim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #6d1f4e;
    margin-bottom: 6px;
}

.studiosim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #43303f;
}

.studiosim-briefing-text strong { color: #a8326b; }
.studiosim-briefing-text em { color: #9a3412; font-style: italic; }

.studiosim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #ecd8e3;
    box-shadow: 0 4px 14px rgba(58, 18, 48, 0.07);
}

.studiosim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #6d1f4e;
    border-bottom: 2px solid #f3e3ec;
    padding-bottom: 8px;
}

.studiosim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #3a1230;
    margin: 14px 0 6px;
}

.studiosim-container select,
.studiosim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #e2c4d4;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fdf7fa;
    color: #2a1b2e;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.studiosim-container select:focus,
.studiosim-container input[type="number"]:focus {
    outline: none;
    border-color: #a8326b;
    box-shadow: 0 0 0 3px rgba(168, 50, 107, 0.15);
}

.studiosim-container select option {
    background-color: #ffffff;
    color: #2a1b2e;
}

.studiosim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #a8326b;
}

.studiosim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #6d1f4e;
    margin-top: 4px;
}

.studiosim-range-readout span:last-child {
    color: #1f7a55;
    font-weight: 800;
}

.studiosim-hint {
    font-size: 0.8rem;
    color: #8a6a7c;
    margin-top: 4px;
    line-height: 1.4;
}

.studiosim-matrix {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.studiosim-matrix-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #fbf2f7;
    border: 1px solid #f0dde7;
    border-radius: 9px;
    padding: 8px 12px;
}

.studiosim-matrix-task {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #43303f;
}

.studiosim-matrix-row select {
    width: 230px;
    flex: 0 0 230px;
}

.studiosim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.studiosim-container .btn-primary {
    background: linear-gradient(135deg, #6d1f4e 0%, #a8326b 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(109, 31, 78, 0.30);
}

.studiosim-container .btn-primary:hover {
    filter: brightness(1.07);
}

.studiosim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #e2c4d4;
    color: #8a6a7c;
}

.studiosim-coach {
    background: #3a1230;
    color: #fbe8f1;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(58, 18, 48, 0.24);
}

.studiosim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f4c977;
    margin-bottom: 8px;
}

.studiosim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.studiosim-coach-body strong { color: #f4c977; }
.studiosim-coach-body em { color: #ffb59a; font-style: italic; }

.studiosim-history,
.studiosim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #ecd8e3;
    box-shadow: 0 4px 14px rgba(58, 18, 48, 0.07);
}

.studiosim-history h3,
.studiosim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #6d1f4e;
}

.studiosim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #43303f;
}

.studiosim-container table#usfHistoryTable th {
    background: #f6e7ef;
    color: #6d1f4e;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #ecd2e0;
}

.studiosim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f4e6ee;
}

.studiosim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #fcf5f9;
}

.studiosim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .studiosim-container {
        padding: 14px;
    }
    .studiosim-header h1 {
        font-size: 1.7rem;
    }
    .studiosim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .studiosim-value {
        font-size: 2rem;
    }
    .studiosim-clock {
        margin-left: 0;
    }
    .studiosim-period-counter {
        font-size: 0.88rem;
    }
    .studiosim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .studiosim-matrix-row {
        flex-wrap: wrap;
    }
    .studiosim-matrix-row select {
        width: 100%;
        flex: 1 1 100%;
    }
    .studiosim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

