(function() {
    'use strict';

    class StudioAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Human + AI Creative Studio`;
            this.version = `1.1.0`;
            // Pre-round domainState snapshots so Undo can roll state back instead
            // of re-accumulating on resubmit (see initialize / calculateResults).
            this._snap = [];

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card.
            this.START_DISTINCT = 70;     // recovering from last spring's -18% vs baseline 100
            this.BASELINE = 100;          // distinctiveness baseline
            this.TARGET_DISTINCT = 100;   // win condition: at or above baseline
            this.START_DELIVERY = 8.0;    // normal cycle for this scope (weeks)
            this.DEADLINE_WEEKS = 5;      // fixed retail launch date
            this.START_ENGAGE = 45;       // 0-100
            this.BUDGET_CAP = 1800;       // EUR 1.8M production budget, in EUR thousands
            this.BASE_COST = 100;         // fixed campaign production overhead (EUR k)
            // Per-task LABOUR cost by deployment mode (EUR k). Human craft is expensive; AI scales cheaply.
            // Anchored so an all-human matrix lands ~EUR 2.3-2.5M (over the 1.8M cap — Common Error 2) and a
            // fully automated matrix lands ~EUR 1.1M, with a balanced matrix fitting inside the cap.
            this.MODE_COST = { human: 540, cocreate: 340, nongen: 260, generative: 180 };
            this.DISTINCT_MAX = 160;      // display/clamp headroom — kept well above the optimal R1-R3 trajectory so distinctiveness is NOT pegged before Round 4 (the Round-4 recalibration lever must stay visible on the final KPI)
            this.DISTINCT_REF = 130;      // "excellent" reference used to normalise the distinctiveness component of the composite (reaching ~baseline+30 maxes that component)

            // Concept truths.
            this.TRUE_WIN = `distinct`;
            this.TRUE_CORE = `concept`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    distinct: this.START_DISTINCT,
                    delivery: this.START_DELIVERY,
                    engage: this.START_ENGAGE,
                    budgetUsed: 0,
                    legalRisk: false,
                    legalHits: 0,
                    overBudget: false,
                    distinctHistory: [this.START_DISTINCT],
                    engageHistory: [this.START_ENGAGE],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    win: `distinct`,
                    core: `concept`,
                    suit: 60,
                    conceptMode: `cocreate`,
                    variantsMode: `generative`,
                    localMode: `cocreate`,
                    analyticsMode: `nongen`,
                    invest: 500,
                    sequence: `humanfirst`,
                    gate: `beforeprint`,
                    override: 60,
                    ratio: `pertask`,
                    diagnose: `correct`,
                    disclosure: `publish`,
                    pitch: `complementary`,
                    conviction: 70
                };
            }
            // Undo support: the framework's Undo pops the last history row,
            // decrements currentPeriod and re-calls initialize() WITHOUT rolling
            // domainState back. If we hold more snapshots than history rows, an
            // Undo just happened -> restore the pre-round domainState so the KPIs
            // and history arrays revert instead of drifting.
            const histLen = (state.history && state.history.length) || 0;
            if (this._snap && this._snap.length > histLen) {
                state.domainState = this._snap.pop();
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const win = document.getElementById(`winInput`);
                const core = document.getElementById(`coreInput`);
                const suit = document.getElementById(`suitInput`);
                if (win) decisions.win = win.value;
                if (core) decisions.core = core.value;
                if (suit) decisions.suit = parseInt(suit.value, 10);
                if (!Number.isFinite(decisions.suit) || decisions.suit < 0 || decisions.suit > 100) {
                    warn(`warn_suit_range`); return false;
                }
            } else if (round === 2) {
                const cm = document.getElementById(`conceptModeInput`);
                const vm2 = document.getElementById(`variantsModeInput`);
                const lm = document.getElementById(`localModeInput`);
                const am = document.getElementById(`analyticsModeInput`);
                const inv = document.getElementById(`investInput`);
                if (cm) decisions.conceptMode = cm.value;
                if (vm2) decisions.variantsMode = vm2.value;
                if (lm) decisions.localMode = lm.value;
                if (am) decisions.analyticsMode = am.value;
                if (inv) decisions.invest = parseFloat(inv.value);
                if (!Number.isFinite(decisions.invest) || decisions.invest < 0 || decisions.invest > this.BUDGET_CAP) {
                    warn(`warn_invest_range`); return false;
                }
            } else if (round === 3) {
                const seq = document.getElementById(`sequenceInput`);
                const gate = document.getElementById(`gateInput`);
                const ov = document.getElementById(`overrideInput`);
                const ratio = document.getElementById(`ratioInput`);
                if (seq) decisions.sequence = seq.value;
                if (gate) decisions.gate = gate.value;
                if (ov) decisions.override = parseInt(ov.value, 10);
                if (ratio) decisions.ratio = ratio.value;
                if (!Number.isFinite(decisions.override) || decisions.override < 0 || decisions.override > 100) {
                    warn(`warn_override_range`); return false;
                }
            } else if (round === 4) {
                const dg = document.getElementById(`diagnoseInput`);
                const ds = document.getElementById(`disclosureInput`);
                const pi = document.getElementById(`pitchInput`);
                const cv = document.getElementById(`convictionInput`);
                if (dg) decisions.diagnose = dg.value;
                if (ds) decisions.disclosure = ds.value;
                if (pi) decisions.pitch = pi.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            // Snapshot the pre-round domainState (serializable) so Undo can roll it
            // back in initialize() instead of re-accumulating on resubmit.
            this._snap.push(JSON.parse(JSON.stringify(ds)));
            const round = state.currentPeriod;

            let distinctDelta = 0, engageDelta = 0, deliveryDelta = 0;
            let spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            // Mode helper: classifies a generative-on-core decision as a flattening event.
            const isGen = (m) => m === `generative`;

            if (round === 1) {
                // Diagnose the win condition and the most-damaging task.
                if (d.win === this.TRUE_WIN) {
                    distinctDelta += 10; coachKey = `coach_r1_win_right`;
                } else if (d.win === `polish`) {
                    distinctDelta += 1; engageDelta += 2; coachKey = `coach_r1_polish`;
                } else if (d.win === `speed`) {
                    distinctDelta -= 6; deliveryDelta -= 0.4; coachKey = `coach_r1_speed`;
                } else { // price
                    distinctDelta -= 8; coachKey = `coach_r1_price`;
                }

                // The creative core (concept & voice) is where mis-balancing is most damaging.
                if (d.core === this.TRUE_CORE) {
                    distinctDelta += 8;
                    if (d.win === this.TRUE_WIN) coachKey = `coach_r1_diag_sharp`;
                } else if (d.core === `tagging`) {
                    distinctDelta -= 8; coachKey = `coach_r1_tagging`;
                } else {
                    distinctDelta -= 4; coachKey = `coach_r1_scalable`;
                }

                // Clarity on amplify-vs-protect.
                if (d.suit >= 60) { distinctDelta += 5; }
                else if (d.suit <= 25) { distinctDelta -= 6; coachKey = `coach_r1_lowsuit`; }

                summaryKey = (d.win === this.TRUE_WIN && d.core === this.TRUE_CORE) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // The core decision: deploy generative vs non-generative AI per task.
                // Creative core: humans/co-creation amplify; generative-AI-led FLATTENS (the -18% trap).
                switch (d.conceptMode) {
                    case `human`: distinctDelta += 8; deliveryDelta += 0.5; break;
                    case `cocreate`: distinctDelta += 12; engageDelta += 3; break;
                    case `generative`: distinctDelta -= 22; deliveryDelta -= 1.2; ds.legalRisk = true; ds.legalHits += 1; coachKey = `coach_r2_autocore`; break;
                    case `nongen`: distinctDelta -= 2; coachKey = `coach_r2_nongencore`; break;
                }

                // Variant production: generative AI is the right place — scales output, compresses time.
                switch (d.variantsMode) {
                    case `generative`: deliveryDelta -= 1.4; engageDelta += 6; distinctDelta += 2; break;
                    case `cocreate`: deliveryDelta -= 0.6; engageDelta += 3; break;
                    case `human`: deliveryDelta += 1.2; distinctDelta += 2; coachKey = (coachKey === `coach_default`) ? `coach_r2_humanvariants` : coachKey; break;
                    case `nongen`: deliveryDelta += 0.3; coachKey = (coachKey === `coach_default`) ? `coach_r2_nongenvariants` : coachKey; break;
                }

                // Localisation: generative / co-creation scales markets without touching the core.
                switch (d.localMode) {
                    case `generative`: deliveryDelta -= 0.9; engageDelta += 4; break;
                    case `cocreate`: deliveryDelta -= 0.4; engageDelta += 3; break;
                    case `human`: deliveryDelta += 0.8; break;
                    case `nongen`: deliveryDelta += 0.2; break;
                }

                // Audience modelling & prediction: this is NON-GENERATIVE. Using it sharpens targeting
                // and never touches a creative asset. Avoiding it = the generative/non-generative
                // confusion (Common Error 3).
                switch (d.analyticsMode) {
                    case `nongen`: engageDelta += 12; distinctDelta += 2; coachKey = (coachKey === `coach_default`) ? `coach_r2_analytics_right` : coachKey; break;
                    case `cocreate`: engageDelta += 7; break;
                    case `human`: engageDelta -= 6; coachKey = `coach_r2_humananalytics`; break;
                    case `generative`: engageDelta -= 4; distinctDelta -= 2; coachKey = `coach_r2_genanalytics`; break;
                }

                // Labour cost of the deployment matrix. Human-led work is expensive and pushes an
                // all-human matrix over the EUR 1.8M cap (Common Error 2 — all-human refusal blows the
                // budget); AI modes are cheap. This makes the Budget KPI a live differentiator rather
                // than a constant.
                spend += this.BASE_COST
                    + (this.MODE_COST[d.conceptMode]   || 0)
                    + (this.MODE_COST[d.variantsMode]  || 0)
                    + (this.MODE_COST[d.localMode]     || 0)
                    + (this.MODE_COST[d.analyticsMode] || 0);

                // Throughput investment: helps if pointed at production (variants/localisation are
                // generative/co-creation), wasted/harmful if the core was automated.
                spend += d.invest;
                const productionScaled = isGen(d.variantsMode) || d.variantsMode === `cocreate` || isGen(d.localMode) || d.localMode === `cocreate`;
                if (productionScaled) {
                    if (d.invest >= 400 && d.invest <= 900) { deliveryDelta -= 1.0; engageDelta += 3; }
                    else if (d.invest > 900) { deliveryDelta -= 1.2; distinctDelta -= 4; coachKey = `coach_r2_overinvest`; }
                    else { deliveryDelta -= 0.3; }
                } else if (d.invest >= 400) {
                    distinctDelta -= 3; coachKey = (coachKey === `coach_default`) ? `coach_r2_misinvest` : coachKey;
                }

                // Coach for the well-balanced matrix.
                const coreProtected = (d.conceptMode === `human` || d.conceptMode === `cocreate`);
                const balancedMatrix = coreProtected && isGen(d.variantsMode) && d.analyticsMode === `nongen`;
                if (balancedMatrix && coachKey === `coach_default`) coachKey = `coach_r2_balanced`;

                summaryKey = balancedMatrix ? `sum_r2_good` : (d.conceptMode === `generative` ? `sum_r2_flat` : `sum_r2_weak`);
            } else if (round === 3) {
                // Orchestrate the human-AI workflow and ship.
                switch (d.sequence) {
                    case `humanfirst`: distinctDelta += 10; engageDelta += 2; deliveryDelta -= 0.3; coachKey = `coach_r3_humanfirst`; break;
                    case `aifirst`: distinctDelta -= 12; deliveryDelta -= 0.8; ds.legalRisk = true; ds.legalHits += 1; coachKey = `coach_r3_aifirst`; break;
                    case `parallel`: distinctDelta -= 4; deliveryDelta += 0.4; coachKey = `coach_r3_parallel`; break;
                }

                // The rights / likeness / disclosure review gate (Common Error 5).
                switch (d.gate) {
                    case `beforeprint`:
                        if (ds.legalRisk) { ds.legalRisk = false; coachKey = `coach_r3_gatecaught`; }
                        distinctDelta += 3; deliveryDelta += 0.4;
                        break;
                    case `spotcheck`:
                        if (ds.legalRisk && ds.legalHits >= 1) { /* sample misses it */ }
                        deliveryDelta += 0.1;
                        break;
                    case `none`:
                        ds.legalHits += 1; ds.legalRisk = true; deliveryDelta -= 0.2; coachKey = `coach_r3_nogate`;
                        break;
                }

                // Human override / refinement of AI output keeps it on-brand.
                if (d.override >= 60) { distinctDelta += 8; engageDelta += 2; }
                else if (d.override <= 25) { distinctDelta -= 8; coachKey = (coachKey === `coach_default`) ? `coach_r3_nooverride` : coachKey; }

                // Per-task ratio vs one flat ratio (Common Error 4).
                if (d.ratio === `pertask`) {
                    distinctDelta += 8; engageDelta += 3;
                    if (d.sequence === `humanfirst` && coachKey === `coach_r3_humanfirst`) coachKey = `coach_r3_pertask`;
                } else {
                    distinctDelta -= 6; deliveryDelta += 0.3; coachKey = `coach_r3_flatratio`;
                }

                summaryKey = (d.sequence === `humanfirst` && d.gate === `beforeprint` && d.ratio === `pertask`) ? `sum_r3_good`
                    : (d.gate === `none` ? `sum_r3_legal` : `sum_r3_weak`);
            } else if (round === 4) {
                // Launch results & recalibrate.
                switch (d.diagnose) {
                    case `correct`: distinctDelta += 8; engageDelta += 4; coachKey = `coach_r4_diag_right`; break;
                    case `moreauto`: distinctDelta -= 10; coachKey = `coach_r4_moreauto`; break;
                    case `lessai`: deliveryDelta += 1.0; distinctDelta += 2; coachKey = `coach_r4_lessai`; break;
                    case `ignore`: distinctDelta -= 8; engageDelta -= 4; coachKey = `coach_r4_ignore`; break;
                }

                // AI-disclosure for the brand-safety board (governance). Disclosure is TRANSPARENCY —
                // it pre-empts disclosure obligations but does NOT retroactively catch a rights/likeness
                // infringement. A live legal flag from a skipped print gate (Common Error 5) must persist;
                // only the Round-3 before-print review gate clears it.
                switch (d.disclosure) {
                    case `publish`:
                        distinctDelta += 2;
                        coachKey = (coachKey === `coach_default`) ? `coach_r4_disclose` : coachKey;
                        break;
                    case `quiet`:
                        ds.legalHits += 1; ds.legalRisk = true; coachKey = `coach_r4_quiet`;
                        break;
                }

                // The forward operating model.
                switch (d.pitch) {
                    case `complementary`: distinctDelta += 10; engageDelta += 3; coachKey = (d.diagnose === `correct`) ? `coach_r4_complementary` : coachKey; break;
                    case `aifirst`: distinctDelta -= 12; coachKey = `coach_r4_pitchauto`; break;
                    case `humanonly`: deliveryDelta += 1.2; distinctDelta += 1; coachKey = `coach_r4_pitchhuman`; break;
                }

                // Conviction nudges distinctiveness.
                distinctDelta += Math.round((d.conviction - 60) / 10);

                summaryKey = (d.diagnose === `correct` && d.pitch === `complementary` && d.disclosure === `publish`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting.
            ds.budgetUsed = Math.round(ds.budgetUsed + spend);
            ds.overBudget = ds.budgetUsed > this.BUDGET_CAP;

            // Apply deltas with headroom. Distinctiveness can climb above baseline; engagement 0-100.
            ds.distinct = Math.max(0, Math.min(this.DISTINCT_MAX, ds.distinct + distinctDelta));
            ds.engage = Math.max(0, Math.min(100, ds.engage + engageDelta));
            ds.delivery = Math.max(2, Math.round((ds.delivery + deliveryDelta) * 10) / 10);

            ds.distinctHistory.push(Math.round(ds.distinct));
            ds.engageHistory.push(Math.round(ds.engage));

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            // Advance the briefing / decision panel to the next round SYNCHRONOUSLY.
            // The framework increments currentPeriod right after this returns, so the
            // old deferred setTimeout read the already-incremented period and revealed
            // the round-after-next panel (after Round 1 it showed Round 3's controls
            // while validateDecisions still read the hidden Round 2 inputs, so the
            // player's visible choices were ignored). currentPeriod is still N here,
            // so N+1 is correct. Skip past the last round.
            if (state.currentPeriod < this.ROUNDS.length) {
                this._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }

            return {
                period: state.currentPeriod,
                distinct: Math.round(ds.distinct),
                distinctDelta: Math.round(distinctDelta),
                engage: Math.round(ds.engage),
                engageDelta: Math.round(engageDelta),
                delivery: ds.delivery,
                budgetUsed: ds.budgetUsed,
                overBudget: ds.overBudget,
                legalRisk: ds.legalRisk,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
