            uiManager.bind(`distinctDisplay`, `domainState.distinct`, (v) => {
                const card = document.querySelector(`.studiosim-card-distinct`);
                if (card) {
                    card.classList.toggle(`studiosim-distinct-win`, Number(v) >= this.TARGET_DISTINCT);
                    card.classList.toggle(`studiosim-distinct-flat`, Number(v) < this.BASELINE - 12);
                }
                return Math.round(Number(v));
            });

            uiManager.bind(`deliveryDisplay`, `domainState.delivery`, (v) => {
                const card = document.querySelector(`.studiosim-card-delivery`);
                if (card) {
                    card.classList.toggle(`studiosim-delivery-ontime`, Number(v) <= this.DEADLINE_WEEKS + 0.001);
                    card.classList.toggle(`studiosim-delivery-late`, Number(v) > this.DEADLINE_WEEKS + 0.001);
                }
                return Number(v).toFixed(1) + ` ` + window.mySimulation.t(`unit_wk`);
            });

            uiManager.bind(`engageDisplay`, `domainState.engage`, (v) => Math.round(v));

            uiManager.bind(`legalDisplay`, `domainState.legalRisk`, (v) => {
                const card = document.querySelector(`.studiosim-card-legal`);
                if (card) card.classList.toggle(`studiosim-legal-flag`, v === true || v === `true`);
                return (v === true || v === `true`) ? window.mySimulation.t(`legal_flagged`) : window.mySimulation.t(`legal_clear`);
            });

            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                const bar = document.querySelector(`.studiosim-budget-bar`);
                if (bar) bar.classList.toggle(`studiosim-over-budget`, Number(v) > this.BUDGET_CAP);
                const lang = window.mySimulation ? window.mySimulation.language : `en`;
                const used = Math.round(Number(v));
                const cap = this.BUDGET_CAP;
                if (lang === `es`) {
                    // Spanish: dot thousands, symbol after the value.
                    return this._fmtKDot(used) + `k € / ` + this._fmtKDot(cap) + `k €`;
                }
                // English: comma thousands, symbol before the value.
                return `€` + this._fmtK(used) + `k / €` + this._fmtK(cap) + `k`;
            });

            // Suitability slider readout.
            const suit = document.getElementById(`suitInput`);
            const suitReadout = document.getElementById(`suitReadout`);
            if (suit && suitReadout) {
                suitReadout.textContent = suit.value;
                suit.addEventListener(`input`, function() { suitReadout.textContent = suit.value; });
            }

            // Override slider readout.
            const ov = document.getElementById(`overrideInput`);
            const ovReadout = document.getElementById(`overrideReadout`);
            if (ov && ovReadout) {
                ovReadout.textContent = ov.value;
                ov.addEventListener(`input`, function() { ovReadout.textContent = ov.value; });
            }
        }

        _fmtK(n) {
            // Group thousands with a comma for English-style EUR thousands labels.
            return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, `,`);
        }

        _fmtKDot(n) {
            // Group thousands with a dot for Spanish-style EUR thousands labels.
            return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, `.`);
        }

