        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const distinct = Math.round(ds.distinct);
            const engage = Math.round(ds.engage);
            const delivery = ds.delivery;
            const onTime = delivery <= this.DEADLINE_WEEKS + 0.001;
            const onBudget = ds.budgetUsed <= this.BUDGET_CAP;
            const distinctWin = distinct >= this.TARGET_DISTINCT;
            const legal = ds.legalRisk;

            const composite = Math.round(
                Math.min(100, (distinct / this.DISTINCT_REF) * 100) * 0.40 +
                engage * 0.25 +
                (onTime ? 100 : Math.max(0, 100 - (delivery - this.DEADLINE_WEEKS) * 30)) * 0.20 +
                (onBudget ? 100 : 0) * 0.10 +
                (legal ? 0 : 100) * 0.05
            );

            let performance = `Forgettable Relaunch`;
            if (distinctWin && onTime && onBudget && !legal && composite >= 78) performance = `Orchestrated Studio`;
            else if (distinctWin && onTime && !legal) performance = `Distinctive & On Time`;
            else if (onTime && onBudget && !distinctWin) performance = `On Time, Forgettable`;
            else if (legal) performance = `Legal Exposure Live`;
            else if (!onTime) performance = `Missed the Shelf`;

            const insights = [];
            if (distinctWin && onTime && onBudget && !legal) insights.push(window.mySimulation.t(`insight_orchestrated`));
            else if (onTime && !distinctWin) insights.push(window.mySimulation.t(`insight_forgettable`));
            else if (!onTime) insights.push(window.mySimulation.t(`insight_late`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (legal) insights.push(window.mySimulation.t(`insight_legal`));
            if (!onBudget) insights.push(window.mySimulation.t(`insight_overbudget`));
            if (distinct >= this.BASELINE + 15) insights.push(window.mySimulation.t(`insight_above`));
            if (engage >= 70) insights.push(window.mySimulation.t(`insight_engage`));

            return {
                distinct: distinct,
                engage: engage,
                delivery: delivery,
                onTime: onTime,
                onBudget: onBudget,
                legal: legal,
                composite: composite,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.legalRisk) return window.mySimulation.t(`hint_legal`);
            if (ds.distinct < this.BASELINE - 12 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_flat`);
            if (ds.delivery > this.DEADLINE_WEEKS && state.currentPeriod >= 2) return window.mySimulation.t(`hint_late`);
            if (ds.overBudget) return window.mySimulation.t(`hint_budget`);
            if (ds.distinct >= this.TARGET_DISTINCT && ds.delivery <= this.DEADLINE_WEEKS && !ds.legalRisk) return window.mySimulation.t(`hint_strong`);
            return null;
        }

